+
+const VERSION: &str = "1.5.1";
+const AUTHOR: &str = "Sven-Hendrik Haase <svenstaro@gmail.com>";
+
+#[derive(Parser, Debug)]
+#[command(
+    name = "genact",
+    author = AUTHOR,
+    version = VERSION,
+    about = "A nonsense activity generator",
+    disable_version_flag = true
+)]
+struct Cli {
+    #[arg(short = 'l', long = "list-modules", help = "List available modules")]
