+        num_args = 1,
+        help = "Run only these modules"
+    )]
+    modules: Vec<Module>,
+
+    #[arg(
+        short = 's',
+        long = "speed-factor",
+        value_parser = parse_speed_factor,
+        default_value = "1",
+        help = "Global speed factor"
+    )]
+    speed_factor: f64,
+
+    #[arg(
+        short = 'i',
+        long = "instant-print-lines",
+        default_value = "0",
+        help = "Instantly print this many lines"
+    )]
+    instant_print_lines: usize,
+
+    #[arg(
+        long = "inhibit",
+        action = ArgAction::SetTrue,
+        help = "Keep the computer awake and the display on while genact is running"
+    )]
+    inhibit: bool,
+
+    #[arg(
+        long = "exit-after-time",
+        value_parser = parse_exit_after_time,
+        help = "Exit after running for this long (format example: 2h10min)"
+    )]
+    exit_after_time: Option<Duration>,
+
+    #[arg(
+        long = "exit-after-modules",
+        value_parser = parse_exit_after_modules,
+        help = "Exit after running this many modules"
+    )]
+    exit_after_modules: Option<u64>,
+
+    #[arg(
+        long = "print-completions",
+        value_enum,
+        help = "Generate completion file for a shell"
+    )]
+    print_completions: Option<CompletionShell>,
+
+    #[arg(long = "print-manpage", action = ArgAction::SetTrue, help = "Generate man page")]
+    print_manpage: bool,
+
+    #[arg(short = 'V', long = "version", action = ArgAction::SetTrue, help = "Print version")]
+    version: bool,
+}
+
+#[derive(Copy, Clone, Debug, Eq, PartialEq, ValueEnum)]
+enum Module {
+    #[value(name = "ansible")]
+    Ansible,
+    #[value(name = "bootlog")]
+    Bootlog,
+    #[value(name = "botnet")]
+    Botnet,
+    #[value(name = "bruteforce")]
+    Bruteforce,
+    #[value(name = "cargo")]
+    Cargo,
+    #[value(name = "cc")]
+    Cc,
+    #[value(name = "composer")]
+    Composer,
+    #[value(name = "cryptomining")]
+    Cryptomining,
+    #[value(name = "docker_build")]
+    DockerBuild,
