+            Self::Terraform => "terraform",
+            Self::Uv => "uv",
+            Self::Weblog => "weblog",
+            Self::Wpt => "wpt",
+        }
+    }
+
+    fn all() -> Vec<Self> {
+        vec![
+            Self::Ansible,
