+            Self::Weblog,
+            Self::Wpt,
+        ]
+    }
+}
+
+#[derive(Copy, Clone, Debug, Eq, PartialEq, ValueEnum)]
+enum CompletionShell {
+    #[value(name = "bash")]
+    Bash,
+    #[value(name = "elvish")]
+    Elvish,
+    #[value(name = "fish")]
+    Fish,
+    #[value(name = "powershell")]
+    Powershell,
+    #[value(name = "zsh")]
+    Zsh,
+}
+
+impl CompletionShell {
+    fn into_clap(self) -> clap_complete::Shell {
+        match self {
+            Self::Bash => clap_complete::Shell::Bash,
+            Self::Elvish => clap_complete::Shell::Elvish,
+            Self::Fish => clap_complete::Shell::Fish,
+            Self::Powershell => clap_complete::Shell::PowerShell,
+            Self::Zsh => clap_complete::Shell::Zsh,
+        }
+    }
+}
+
+fn parse_speed_factor(input: &str) -> Result<f64, String> {
+    let value: f64 = input.parse().map_err(|err: std::num::ParseFloatError| err.to_string())?;
+    if value < 0.01 {
+        return Err("Speed factor must be larger than 0.01".to_string());
+    }
+    Ok(value)
+}
+
+fn parse_exit_after_modules(input: &str) -> Result<u64, String> {
+    let value: u64 = input.parse().map_err(|err: std::num::ParseIntError| err.to_string())?;
+    if value == 0 {
+        return Err("Must be larger than 0".to_string());
+    }
+    Ok(value)
+}
+
+fn parse_exit_after_time(input: &str) -> Result<Duration, String> {
+    humantime::parse_duration(input).map_err(|err| err.to_string())
+}
+
+fn invoked_binary_name() -> String {
+    env::args()
+        .next()
+        .and_then(|arg| Path::new(&arg).file_name().map(|name| name.to_string_lossy().into_owned()))
+        .filter(|name| !name.is_empty())
+        .unwrap_or_else(|| "executable".to_string())
+}
+
+fn parsing_command() -> clap::Command {
+    Cli::command().bin_name(invoked_binary_name())
+}
+
+fn metadata_command() -> clap::Command {
+    Cli::command()
+}
+
+fn parse_cli() -> Result<Cli, clap::Error> {
+    let mut cmd = parsing_command();
+    let matches = cmd.try_get_matches()?;
+    Cli::from_arg_matches(&matches)
+}
+
+struct OutputController {
+    stdout: io::Stdout,
+    emissions: usize,
+    instant_print_lines: usize,
+    speed_factor: f64,
+    deadline: Option<Instant>,
+    stop_flag: Arc<AtomicBool>,
+    line_open: bool,
+}
+
+impl OutputController {
+    fn new(
+        instant_print_lines: usize,
+        speed_factor: f64,
+        deadline: Option<Instant>,
+        stop_flag: Arc<AtomicBool>,
+    ) -> Self {
+        Self {
+            stdout: io::stdout(),
+            emissions: 0,
+            instant_print_lines,
+            speed_factor,
+            deadline,
+            stop_flag,
+            line_open: false,
+        }
+    }
+
+    fn is_tty(&self) -> bool {
+        self.stdout.is_terminal()
+    }
+
+    fn should_stop(&self) -> bool {
+        self.stop_flag.load(Ordering::SeqCst)
+            || self.deadline.is_some_and(|deadline| Instant::now() >= deadline)
+    }
+
+    fn ensure_newline(&mut self) -> io::Result<()> {
+        if self.line_open {
+            writeln!(self.stdout)?;
+            self.stdout.flush()?;
+            self.line_open = false;
+        }
+        Ok(())
+    }
+
+    fn line(&mut self, text: &str) -> io::Result<()> {
+        self.ensure_newline()?;
+        writeln!(self.stdout, "{text}")?;
+        self.stdout.flush()?;
+        self.tick(false);
+        Ok(())
+    }
+
+    fn blank_line(&mut self) -> io::Result<()> {
+        self.line("")
+    }
+
+    fn raw(&mut self, text: &str) -> io::Result<()> {
+        write!(self.stdout, "{text}")?;
+        self.stdout.flush()?;
+        self.line_open = !text.ends_with('\n');
+        self.tick(false);
+        Ok(())
+    }
+
+    fn footer(&mut self) -> io::Result<()> {
+        self.ensure_newline()?;
+        writeln!(self.stdout, "Saving work to disk...")?;
+        self.stdout.flush()?;
+        Ok(())
+    }
+
+    fn tick(&mut self, extra_fast: bool) {
+        self.emissions += 1;
+        if !extra_fast && self.emissions > self.instant_print_lines {
+            let base = Duration::from_millis(45);
+            let secs = base.as_secs_f64() / self.speed_factor.max(0.01);
+            if secs > 0.0 {
+                thread::sleep(Duration::from_secs_f64(secs));
+            }
+        }
+    }
+}
+
+#[derive(Copy, Clone, Debug, Eq, PartialEq)]
+enum SceneResult {
+    Finished,
+    Interrupted,
+}
+
+fn main() {
+    if let Err(err) = real_main() {
+        eprintln!("{err}");
+        process::exit(1);
+    }
+}
+
+fn real_main() -> Result<(), Box<dyn std::error::Error>> {
+    let cli = match parse_cli() {
+        Ok(cli) => cli,
+        Err(err) => err.exit(),
+    };
+
+    if cli.version {
+        println!("genact {VERSION}");
+        return Ok(());
+    }
+
+    if cli.list_modules {
+        println!("Available modules:");
+        for module in Module::all() {
+            println!("  {}", module.as_str());
+        }
+        return Ok(());
+    }
+
+    if let Some(shell) = cli.print_completions {
+        let mut cmd = metadata_command();
+        generate(shell.into_clap(), &mut cmd, "genact", &mut io::stdout());
+        return Ok(());
+    }
+
+    if cli.print_manpage {
+        let cmd = metadata_command();
+        let mut buffer = Vec::new();
+        Man::new(cmd).render(&mut buffer)?;
+        let mut page = String::from_utf8(buffer)?;
+        page = page.replace(
+            ".SH VERSION\n1.5.1\n",
+            ".SH VERSION\nv1.5.1\n",
+        );
+        print!("{page}");
+        return Ok(());
+    }
+
+    if cli.inhibit {
+        maybe_warn_inhibit();
+    }
+
+    let stop_flag = Arc::new(AtomicBool::new(false));
+    let signal_flag = Arc::clone(&stop_flag);
+    ctrlc::set_handler(move || {
+        signal_flag.store(true, Ordering::SeqCst);
+    })?;
+
+    let selected_modules = if cli.modules.is_empty() {
+        Module::all()
+    } else {
+        cli.modules.clone()
+    };
+    let deadline = cli.exit_after_time.map(|duration| Instant::now() + duration);
+    let mut out = OutputController::new(
+        cli.instant_print_lines,
+        cli.speed_factor,
+        deadline,
+        stop_flag,
+    );
+    let mut rng = rand::thread_rng();
+    let mut completed_modules = 0_u64;
+
+    loop {
+        let module = *selected_modules
+            .choose(&mut rng)
+            .expect("selected_modules is never empty");
+
+        let result = run_scene(module, &mut out, &mut rng)?;
+        if matches!(result, SceneResult::Finished) {
+            completed_modules += 1;
+            if cli.exit_after_modules.is_some_and(|limit| completed_modules >= limit) {
+                break;
+            }
+        }
+
+        if out.should_stop() {
+            break;
+        }
+    }
+
+    out.footer()?;
+    Ok(())
+}
+
+fn maybe_warn_inhibit() {
+    let uid = env::var("UID").unwrap_or_else(|_| "1000".to_string());
+    let bus_path = format!("/run/user/{uid}/bus");
+    if env::var_os("DBUS_SESSION_BUS_ADDRESS").is_none() && !Path::new(&bus_path).exists() {
+        eprintln!(
+            "WARN: failed to set up idle inhibition: system: I/O error: No such file or directory (os error 2)"
+        );
+    }
+}
+
+fn panic_terminal_width() -> ! {
+    eprintln!();
+    eprintln!("thread 'main' ({}) panicked at src/io.rs:117:9:", process::id());
+    eprintln!("Couldn't get terminal width. Is an interactive terminal attached?");
+    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
+    process::exit(101);
+}
+
+fn terminal_width() -> usize {
+    env::var("COLUMNS")
+        .ok()
+        .and_then(|value| value.parse::<usize>().ok())
+        .filter(|value| *value > 0)
+        .unwrap_or(80)
+}
+
+fn run_scene(
+    module: Module,
+    out: &mut OutputController,
+    rng: &mut rand::rngs::ThreadRng,
+) -> io::Result<SceneResult> {
+    match module {
+        Module::Ansible => run_ansible(out, rng),
+        Module::Bootlog => run_bootlog(out, rng),
+        Module::Botnet => run_botnet(out, rng),
+        Module::Bruteforce => run_bruteforce(out, rng),
+        Module::Cargo => run_cargo(out, rng),
+        Module::Cc => run_cc(out, rng),
+        Module::Composer => run_composer(out, rng),
+        Module::Cryptomining => run_cryptomining(out, rng),
+        Module::DockerBuild => run_docker_build(out, rng),
+        Module::DockerImageRm => run_docker_image_rm(out, rng),
+        Module::Download => run_download(out, rng),
+        Module::Julia => run_julia(out, rng),
+        Module::KernelCompile => run_kernel_compile(out, rng),
+        Module::Memdump => run_memdump(out, rng),
+        Module::Mkinitcpio => run_mkinitcpio(out, rng),
+        Module::Rkhunter => run_rkhunter(out, rng),
+        Module::Simcity => run_simcity(out, rng),
+        Module::Terraform => run_terraform(out, rng),
+        Module::Uv => run_uv(out, rng),
+        Module::Weblog => run_weblog(out, rng),
+        Module::Wpt => run_wpt(out, rng),
+    }
+}
+
+fn run_ansible(out: &mut OutputController, rng: &mut rand::rngs::ThreadRng) -> io::Result<SceneResult> {
+    if !out.is_tty() {
+        panic_terminal_width();
+    }
+
+    let width = terminal_width().max(60);
+    let play_prefix = format!("PLAY [setup {}] ", random_slug(rng, "_"));
+    out.line(&format!("{play_prefix}{}", "*".repeat(width.saturating_sub(play_prefix.len()))))?;
+
+    let hosts: Vec<String> = (0..rng.gen_range(10..22))
+        .map(|_| random_ip(rng))
+        .collect();
+    let tasks = [
+        ("Gathering Facts", vec!["ok"]),
+        ("public_html : make companywiki user", vec!["ok", "changed"]),
+        ("common : install base packages", vec!["ok", "changed", "skipping"]),
+        ("firewall : permit load balancer", vec!["ok", "changed", "failed"]),
+    ];
+
+    for (task_name, statuses) in tasks {
+        out.blank_line()?;
+        let header = format!("TASK [{task_name}] ");
+        out.line(&format!("{header}{}", "*".repeat(width.saturating_sub(header.len()))))?;
+        for host in &hosts {
+            let status = statuses.choose(rng).copied().unwrap_or("ok");
+            let rendered = match status {
+                "ok" => format!("\x1b[32mok: [{host}]\x1b[0m"),
+                "changed" => format!("\x1b[33mchanged: [{host}]\x1b[0m"),
+                "skipping" => format!("\x1b[36mskipping: [{host}]\x1b[0m"),
+                _ => format!("\x1b[31mfailed: [{host}]\x1b[0m"),
+            };
+            out.line(&rendered)?;
+            if out.should_stop() {
+                return Ok(SceneResult::Interrupted);
+            }
+        }
+    }
+
+    Ok(SceneResult::Finished)
+}
+
+fn run_bootlog(out: &mut OutputController, rng: &mut rand::rngs::ThreadRng) -> io::Result<SceneResult> {
+    let vendors = ["SuperCRA", "HackNet", "Compotek", "CoreInit", "PTEC"];
+    let boards = ["TP-N11", "GLX-7", "VX-420", "ZR-3", "OM-99"];
+    let firewire = ["00023b123456789a", "0011223344556677", "00a1b2c3d4e5f601"];
+    for index in 0..90 {
+        let line = match rng.gen_range(0..6) {
+            0 => format!(
+                "ACPI: DMAR 0x{} {:06X} (v01 {} {:<8} {:08X} {:<4} {:08X})",
+                random_hex(rng, 16).to_uppercase(),
+                rng.gen_range(0x90..0x130),
+                vendors.choose(rng).unwrap(),
+                boards.choose(rng).unwrap(),
+                rng.gen_range(1000..99999),
+                "PTEC",
+                rng.gen_range(1..10)
+            ),
+            1 => format!(
+                "DMAR: DRHD base: 0x{} flags: 0x{}",
+                random_hex(rng, 12),
+                random_hex(rng, 4)
+            ),
+            2 => format!(
+                "HackNetACPICPU: Processor [{}] (supports {} throttling states)",
+                (b'A' + (index % 6) as u8) as char,
+                rng.gen_range(4..11)
+            ),
+            3 => format!(
+                "FireWire (OHCI) {}:fw{}: GUID {}",
+                rng.gen_range(0..8),
+                rng.gen_range(0..3),
+                firewire.choose(rng).unwrap()
+            ),
+            4 => format!(
+                "usb {}-{}: new high-speed USB device number {} using xhci_hcd",
+                rng.gen_range(1..4),
+                rng.gen_range(1..8),
+                rng.gen_range(2..64)
+            ),
+            _ => format!(
+                "  {} base 0x{} irq {}",
+                rng.gen_range(2..8),
+                random_hex(rng, 6),
+                rng.gen_range(4..32)
+            ),
+        };
+        out.line(&line)?;
+        if out.should_stop() {
+            return Ok(SceneResult::Interrupted);
+        }
+    }
+
+    Ok(SceneResult::Finished)
+}
+
+fn run_botnet(out: &mut OutputController, rng: &mut rand::rngs::ThreadRng) -> io::Result<SceneResult> {
+    let total = 1799;
+    let mut current = 0;
+    while current < total {
+        current = (current + rng.gen_range(17..91)).min(total);
+        out.raw(&format!("\rEstablishing connections: {current}/{total}"))?;
+        if out.should_stop() {
+            out.ensure_newline()?;
+            return Ok(SceneResult::Interrupted);
+        }
+    }
+    out.ensure_newline()?;
+    for cluster in 0..4 {
+        out.line(&format!("  Cluster #{cluster:02} ({} nodes)", rng.gen_range(110..320)))?;
+        if out.should_stop() {
+            return Ok(SceneResult::Interrupted);
+        }
+    }
+    Ok(SceneResult::Finished)
+}
+
+fn run_bruteforce(out: &mut OutputController, rng: &mut rand::rngs::ThreadRng) -> io::Result<SceneResult> {
+    out.line("=> Hashes to decrypt")?;
+    let hashes: Vec<String> = (0..7).map(|_| random_hex(rng, 64)).collect();
+    for hash in &hashes {
+        out.line(&format!("  {hash}"))?;
+    }
+    out.blank_line()?;
+
+    for percent in (0..=100).step_by(7) {
+        let filled = percent / 4;
+        let bar = format!("{}{}", "#".repeat(filled), " ".repeat(25 - filled));
+        out.raw(&format!("\r=> Extracting Rainbow Table [{bar}] {percent:>3}%"))?;
+        if out.should_stop() {
+            out.ensure_newline()?;
+            return Ok(SceneResult::Interrupted);
+        }
+    }
+    out.ensure_newline()?;
+    out.line("=> Begin matching")?;
+
+    let mut progress = [0usize; 7];
+    for _ in 0..24 {
+        let mut frame = String::new();
+        for (slot, hash) in hashes.iter().enumerate() {
+            progress[slot] = (progress[slot] + rng.gen_range(1..7)).min(hash.len());
+            let (matched, remaining) = hash.split_at(progress[slot]);
+            let _ = writeln!(
+                frame,
+                " :: \x1b[32m{matched}\x1b[31m{remaining}\x1b[0m ::"
+            );
+        }
+        out.raw(&frame)?;
+        if progress.iter().any(|value| *value > 0) {
+            out.raw("\x1b[7A")?;
+        }
+        if out.should_stop() {
+            out.ensure_newline()?;
+            return Ok(SceneResult::Interrupted);
+        }
+    }
+    out.ensure_newline()?;
+    Ok(SceneResult::Finished)
