fn random_symbol(rng: &mut rand::rngs::ThreadRng) -> String {
    let pieces = rng.gen_range(1..=3);
    let mut parts = Vec::new();
    for _ in 0..pieces {
        parts.push(random_word(rng));
    }
    parts.join("-")
}

