fn random_filename(rng: &mut rand::rngs::ThreadRng) -> String {
    let ext = ["html", "opus", "iso", "zip", "rpm", "rar", "mp4", "json"]
        .choose(rng)
        .copied()
        .unwrap_or("bin");
    format!("{}.{}", random_symbol(rng), ext)
}

fn random_ipv4(rng: &mut rand::rngs::ThreadRng) -> String {
    format!(
        "{}.{}.{}.{}",
        rng.gen_range(1..=255),
        rng.gen_range(0..=255),
        rng.gen_range(0..=255),
        rng.gen_range(1..=255)
    )
}

fn random_ipv6(rng: &mut rand::rngs::ThreadRng) -> String {
    (0..8)
        .map(|_| format!("{:x}", rng.gen_range(0_u16..=0xffff)))
        .collect::<Vec<_>>()
        .join(":")
}

fn random_ip(rng: &mut rand::rngs::ThreadRng) -> String {
    if rng.gen_bool(0.4) {
        random_ipv6(rng)
    } else {
        random_ipv4(rng)
    }
}

fn random_hex(rng: &mut rand::rngs::ThreadRng, len: usize) -> String {
    let mut value = String::with_capacity(len);
    const HEX: &[u8] = b"0123456789abcdef";
    for _ in 0..len {
        value.push(HEX[rng.gen_range(0..HEX.len())] as char);
    }
    value
}

fn random_path(rng: &mut rand::rngs::ThreadRng, depth: usize, sep: &str) -> String {
    (0..depth)
        .map(|_| random_word(rng).to_string())
        .collect::<Vec<_>>()
        .join(sep)
}

fn random_kernel_path(rng: &mut rand::rngs::ThreadRng) -> String {
    let roots = [
        "arch/alpha/kernel",
        "arch/arm/mach-imx",
        "arch/x86/kernel",
        "drivers/block",
        "drivers/gpu/drm",
        "drivers/media/pci",
        "drivers/net/wireless/realtek/rtlwifi",
        "fs/nfs",
        "kernel/irq",
        "mm",
        "sound/core",
        "tools/testing/selftests/x86",
    ];
    format!(
        "{}/{}",
        roots.choose(rng).copied().unwrap_or("drivers/net"),
        random_symbol(rng)
    )
}

fn random_compile_line(rng: &mut rand::rngs::ThreadRng) -> String {
    let compiler = ["gcc", "clang"].choose(rng).copied().unwrap_or("gcc");
    let opt = ["-O0", "-O1", "-O2", "-O3", "-Os"]
        .choose(rng)
        .copied()
        .unwrap_or("-O2");
    let warnings = [
        "-Wall -Wextra -Wold-style-definition",
        "-Wall -Wno-sign-compare -fgnu89-inline",
        "-Wall -Wno-parentheses -Wundef",
        "-Wall -Wextra -Wundef -Wold-style-definition",
    ]
    .choose(rng)
    .copied()
    .unwrap_or("-Wall");
    let mut includes = Vec::new();
    for _ in 0..rng.gen_range(10..24) {
        includes.push(format!("-I{}", random_kernel_path(rng)));
    }
    let mut defines = Vec::new();
    for _ in 0..rng.gen_range(2..7) {
        let define = match rng.gen_range(0..5) {
            0 => "DEBUG".to_string(),
            1 => "_REENTRANT".to_string(),
            2 => "LIBS_REENTRANT".to_string(),
            3 => format!("MODULE_NAME={}", random_word(rng)),
            _ => format!("NAMESPACE={}", random_word(rng)),
        };
        defines.push(format!("-D{define}"));
    }
    format!(
        "{compiler} -c {opt} {warnings} {} {} -o {}.o",
        includes.join(" "),
        defines.join(" "),
        random_kernel_path(rng)
    )
}

fn random_wpt_path(rng: &mut rand::rngs::ThreadRng) -> String {
    let top = [
        "css", "html", "encoding", "WebGL", "webaudio", "cookies", "streams", "webrtc",
        "navigation-api", "selectors", "svg", "canvas", "loading", "dom",
    ]
    .choose(rng)
    .copied()
    .unwrap_or("html");
    format!(
        "/{top}/{}/{}/test-{}.html",
        random_word(rng),
        random_word(rng),
        rng.gen_range(1..500)
    )
}

fn random_test_name(rng: &mut rand::rngs::ThreadRng) -> String {
    format!("test_{}{}", random_word(rng), rng.gen_range(1..400))
}

fn random_stack_frame(rng: &mut rand::rngs::ThreadRng) -> String {
    if rng.gen_bool(0.35) {
        "<unknown>".to_string()
    } else {
        format!(
            "http://web-platform.test:8000{}:{}:{}",
            random_wpt_path(rng),
            rng.gen_range(1..160),
            rng.gen_range(1..99)
        )
    }
}

