struct OutputController {
    stdout: io::Stdout,
    emissions: usize,
    instant_print_lines: usize,
    speed_factor: f64,
    deadline: Option<Instant>,
    line_open: bool,
}

impl OutputController {
    fn new(instant_print_lines: usize, speed_factor: f64, deadline: Option<Instant>) -> Self {
        Self {
            stdout: io::stdout(),
            emissions: 0,
            instant_print_lines,
            speed_factor,
            deadline,
            line_open: false,
        }
    }

    fn is_tty(&self) -> bool {
        self.stdout.is_terminal()
    }

    fn should_stop(&self) -> bool {
        STOP_REQUESTED.load(Ordering::SeqCst)
            || self
                .deadline
                .is_some_and(|deadline| Instant::now() >= deadline)
    }

    fn ensure_newline(&mut self) -> io::Result<()> {
        if self.line_open {
            writeln!(self.stdout)?;
            self.stdout.flush()?;
            self.line_open = false;
        }
        Ok(())
    }

    fn line(&mut self, text: &str) -> io::Result<()> {
        self.ensure_newline()?;
        writeln!(self.stdout, "{text}")?;
        self.stdout.flush()?;
        self.emissions += 1;
        self.pace();
        Ok(())
    }

    fn blank_line(&mut self) -> io::Result<()> {
        self.line("")
    }

    fn raw(&mut self, text: &str) -> io::Result<()> {
        write!(self.stdout, "{text}")?;
        self.stdout.flush()?;
        self.line_open = !text.ends_with('\n');
        self.emissions += 1;
        self.pace();
        Ok(())
    }

    fn footer(&mut self) -> io::Result<()> {
        self.ensure_newline()?;
        writeln!(self.stdout, "Saving work to disk...")?;
        self.stdout.flush()?;
        Ok(())
    }

    fn pace(&self) {
        if self.emissions > self.instant_print_lines {
            let delay = Duration::from_millis(45);
            let secs = delay.as_secs_f64() / self.speed_factor.max(0.01);
            if secs > 0.0 {
                thread::sleep(Duration::from_secs_f64(secs));
            }
        }
    }
}

