    Finished,
    Interrupted,
}

struct SimpleRng(u64);

impl SimpleRng {
    fn seeded() -> Self {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos() as u64;
        Self(now ^ ((process::id() as u64) << 16) ^ 0x9e37_79b9_7f4a_7c15)
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.0 | 1;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    fn u8(&mut self) -> u8 {
        self.next_u64() as u8
    }

    fn usize_range(&mut self, start: usize, end: usize) -> usize {
        if end <= start {
            return start;
        }
        start + (self.next_u64() as usize % (end - start))
    }

    fn usize_range_inclusive(&mut self, start: usize, end: usize) -> usize {
        if end <= start {
            return start;
        }
        self.usize_range(start, end + 1)
    }

    fn u64_range(&mut self, start: u64, end: u64) -> u64 {
        if end <= start {
            return start;
        }
        start + (self.next_u64() % (end - start))
    }

    fn u64_range_inclusive(&mut self, start: u64, end: u64) -> u64 {
        if end <= start {
            return start;
        }
        self.u64_range(start, end + 1)
    }

    fn f64(&mut self) -> f64 {
        let numerator = (self.next_u64() >> 11) as f64;
        numerator / ((1_u64 << 53) as f64)
    }

    fn f64_range(&mut self, start: f64, end: f64) -> f64 {
        if end <= start {
            return start;
        }
        start + self.f64() * (end - start)
    }

    fn chance(&mut self, probability: f64) -> bool {
        self.f64() < probability
    }

    fn choose<'a, T>(&mut self, values: &'a [T]) -> &'a T {
        &values[self.usize_range(0, values.len())]
    }
}

extern "C" fn handle_sigint(_: i32) {
    STOP_REQUESTED.store(true, Ordering::SeqCst);
}

fn main() {
    if let Err(error) = real_main() {
        eprintln!("{error}");
        process::exit(1);
    }
}

fn real_main() -> Result<(), Box<dyn std::error::Error>> {
    let bin_name = invoked_binary_name();
    let args: Vec<String> = env::args().skip(1).collect();
    let parsed = parse_args(&bin_name, &args).map_err(|message| io::Error::other(message))?;

    if parsed.help {
        print!("{}", help_text(&bin_name));
        return Ok(());
    }

    if parsed.version {
        println!("genact {VERSION}");
        return Ok(());
    }

    if parsed.list_modules {
        println!("Available modules:");
        for value in MODULE_VALUES {
            println!("  {value}");
        }
        return Ok(());
    }

    if let Some(shell) = parsed.print_completions {
        match shell {
            CompletionShell::Bash => print!("{BASH_COMPLETIONS}"),
            CompletionShell::Elvish => print!("{ELVISH_COMPLETIONS}"),
            CompletionShell::Fish => print!("{FISH_COMPLETIONS}"),
            CompletionShell::Powershell => print!("{POWERSHELL_COMPLETIONS}"),
            CompletionShell::Zsh => print!("{ZSH_COMPLETIONS}"),
        }
        return Ok(());
    }

    if parsed.print_manpage {
        print!("{MANPAGE_TEXT}");
        return Ok(());
    }

    if parsed.inhibit {
        maybe_warn_inhibit();
    }

    unsafe {
        let _ = signal(SIGINT, handle_sigint);
    }

    let selected_modules = if parsed.modules.is_empty() {
        Module::ALL.to_vec()
    } else {
        parsed.modules.clone()
    };

    let deadline = parsed.exit_after_time.map(|duration| Instant::now() + duration);
    let mut output = OutputController::new(
        parsed.instant_print_lines,
        parsed.speed_factor,
        deadline,
    );
    let mut rng = SimpleRng::seeded();
    let mut completed_modules = 0_u64;

    loop {
        let module = *rng.choose(&selected_modules);
        let result = run_scene(module, &mut output, &mut rng)?;
        if result == SceneResult::Finished {
            completed_modules += 1;
            if parsed
                .exit_after_modules
                .is_some_and(|limit| completed_modules >= limit)
            {
                break;
            }
        }
        if output.should_stop() {
            break;
        }
    }

    output.footer()?;
    Ok(())
}

fn help_text(bin_name: &str) -> String {
    HELP_TEMPLATE.replace("{bin}", bin_name)
}

fn invoked_binary_name() -> String {
    env::args()
        .next()
        .and_then(|value| {
            Path::new(&value)
                .file_name()
                .map(|name| name.to_string_lossy().into_owned())
        })
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "executable".to_string())
}

fn parse_args(bin_name: &str, args: &[String]) -> Result<ParsedArgs, String> {
    let mut parsed = ParsedArgs::default();
    let mut index = 0;

    while index < args.len() {
        let arg = &args[index];
        match arg.as_str() {
            "-h" | "--help" => {
                parsed.help = true;
                return Ok(parsed);
            }
            "-V" | "--version" => {
                parsed.version = true;
                return Ok(parsed);
            }
            "-l" | "--list-modules" => {
                parsed.list_modules = true;
                index += 1;
            }
            "-m" | "--modules" => {
                let value = require_value(args, index, "--modules <MODULES>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                let module = Module::parse(value).ok_or_else(|| {
                    invalid_enum_value(
                        value,
                        "--modules <MODULES>",
                        &MODULE_VALUES,
                        best_suggestion(value, &MODULE_VALUES),
                    )
                })?;
                parsed.modules.push(module);
                index += 2;
            }
            "-s" | "--speed-factor" => {
                let value = require_value(args, index, "--speed-factor <SPEED_FACTOR>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.speed_factor = parse_speed_factor(value)?;
                index += 2;
            }
            "-i" | "--instant-print-lines" => {
                let value =
                    require_value(args, index, "--instant-print-lines <INSTANT_PRINT_LINES>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.instant_print_lines = value.parse::<usize>().map_err(|err| {
                    invalid_value_message(
                        value,
                        "--instant-print-lines <INSTANT_PRINT_LINES>",
                        &err.to_string(),
                    )
                })?;
                index += 2;
            }
            "--inhibit" => {
                parsed.inhibit = true;
                index += 1;
            }
            "--exit-after-time" => {
                let value = require_value(args, index, "--exit-after-time <EXIT_AFTER_TIME>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.exit_after_time = Some(parse_duration_flag(value)?);
                index += 2;
            }
            "--exit-after-modules" => {
                let value =
                    require_value(args, index, "--exit-after-modules <EXIT_AFTER_MODULES>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.exit_after_modules = Some(parse_exit_after_modules(value)?);
                index += 2;
            }
            "--print-completions" => {
                let value = require_value(args, index, "--print-completions <shell>")?;
                if value.starts_with('-') {
                    return Err(unexpected_argument(bin_name, value));
                }
                parsed.print_completions = Some(CompletionShell::parse(value).ok_or_else(|| {
                    invalid_enum_value(value, "--print-completions <shell>", &SHELL_VALUES, None)
                })?);
                index += 2;
            }
            "--print-manpage" => {
                parsed.print_manpage = true;
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--modules=") => {
                let module = Module::parse(value).ok_or_else(|| {
                    invalid_enum_value(
                        value,
                        "--modules <MODULES>",
                        &MODULE_VALUES,
                        best_suggestion(value, &MODULE_VALUES),
                    )
                })?;
                parsed.modules.push(module);
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--speed-factor=") => {
                parsed.speed_factor = parse_speed_factor(value)?;
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--instant-print-lines=") => {
                parsed.instant_print_lines = value.parse::<usize>().map_err(|err| {
                    invalid_value_message(
                        value,
                        "--instant-print-lines <INSTANT_PRINT_LINES>",
                        &err.to_string(),
                    )
                })?;
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--exit-after-time=") => {
                parsed.exit_after_time = Some(parse_duration_flag(value)?);
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--exit-after-modules=") => {
                parsed.exit_after_modules = Some(parse_exit_after_modules(value)?);
                index += 1;
            }
            _ if let Some(value) = arg.strip_prefix("--print-completions=") => {
                parsed.print_completions = Some(CompletionShell::parse(value).ok_or_else(|| {
                    invalid_enum_value(value, "--print-completions <shell>", &SHELL_VALUES, None)
                })?);
                index += 1;
            }
            _ => {
                return Err(unexpected_argument(bin_name, arg));
            }
        }
    }

    Ok(parsed)
}

fn require_value<'a>(args: &'a [String], index: usize, flag: &str) -> Result<&'a str, String> {
    args.get(index + 1)
        .map(String::as_str)
        .ok_or_else(|| missing_value(flag))
}

fn missing_value(flag: &str) -> String {
    format!(
        "error: a value is required for '{flag}' but none was supplied\n\nFor more information, try '--help'.\n"
    )
}

fn invalid_value_message(value: &str, flag: &str, reason: &str) -> String {
    format!("error: invalid value '{value}' for '{flag}': {reason}\n\nFor more information, try '--help'.\n")
}

fn parse_speed_factor(value: &str) -> Result<f64, String> {
    let parsed = value
        .parse::<f64>()
        .map_err(|err| invalid_value_message(value, "--speed-factor <SPEED_FACTOR>", &err.to_string()))?;
    if parsed < 0.01 {
        return Err(invalid_value_message(
            value,
            "--speed-factor <SPEED_FACTOR>",
            "Speed factor must be larger than 0.01",
        ));
    }
    Ok(parsed)
}

fn parse_exit_after_modules(value: &str) -> Result<u64, String> {
    let parsed = value.parse::<u64>().map_err(|err| {
        invalid_value_message(value, "--exit-after-modules <EXIT_AFTER_MODULES>", &err.to_string())
    })?;
    if parsed == 0 {
        return Err(invalid_value_message(
            value,
            "--exit-after-modules <EXIT_AFTER_MODULES>",
            "Must be larger than 0",
        ));
    }
    Ok(parsed)
}

fn parse_duration_flag(value: &str) -> Result<Duration, String> {
    parse_duration_value(value).map_err(|reason| {
        invalid_value_message(value, "--exit-after-time <EXIT_AFTER_TIME>", &reason)
    })
}

fn parse_duration_value(value: &str) -> Result<Duration, String> {
    let bytes = value.as_bytes();
    let mut index = 0;
    let mut total = Duration::ZERO;
    while index < bytes.len() {
        if !bytes[index].is_ascii_digit() {
            return Err(format!("expected number at {index}"));
        }
        let start = index;
        while index < bytes.len() && bytes[index].is_ascii_digit() {
            index += 1;
        }
        let number = value[start..index]
            .parse::<u64>()
            .map_err(|_| format!("expected number at {start}"))?;
        if index >= bytes.len() {
            return Err(format!("unknown time unit at {index}"));
        }
        let remainder = &value[index..];
        if remainder.starts_with("ms") {
            total += Duration::from_millis(number);
            index += 2;
        } else if remainder.starts_with("min") {
            total += Duration::from_secs(number * 60);
            index += 3;
        } else if remainder.starts_with('h') {
            total += Duration::from_secs(number * 3600);
            index += 1;
        } else if remainder.starts_with('s') {
            total += Duration::from_secs(number);
            index += 1;
        } else {
            return Err(format!("unknown time unit at {index}"));
        }
    }
    Ok(total)
}

fn invalid_enum_value(
    value: &str,
    flag: &str,
    possible_values: &[&str],
    suggestion: Option<&str>,
) -> String {
    let mut message = format!(
        "error: invalid value '{value}' for '{flag}'\n  [possible values: {}]\n",
        possible_values.join(", ")
    );
    if let Some(candidate) = suggestion {
        let _ = write!(message, "\n  tip: a similar value exists: '{candidate}'\n");
    }
    message.push_str("\nFor more information, try '--help'.\n");
    message
}

fn unexpected_argument(bin_name: &str, argument: &str) -> String {
    format!(
        "error: unexpected argument '{argument}' found\n\nUsage: {bin_name} [OPTIONS]\n\nFor more information, try '--help'.\n"
    )
}

fn best_suggestion<'a>(value: &str, options: &'a [&str]) -> Option<&'a str> {
    let mut best = None;
    let mut best_score = 0;
    for option in options {
        let score = lcs_score(value, option);
        if score > best_score
            || (score == best_score
                && best
                    .is_some_and(|current: &str| option.len() < current.len()))
        {
            best = Some(*option);
            best_score = score;
        }
    }
    if best_score >= 3 {
        best
    } else {
        None
    }
}

fn lcs_score(left: &str, right: &str) -> usize {
    let left_chars: Vec<char> = left.chars().collect();
    let right_chars: Vec<char> = right.chars().collect();
    let mut dp = vec![0usize; right_chars.len() + 1];
    for l in &left_chars {
        let mut previous = 0;
        for (index, r) in right_chars.iter().enumerate() {
            let stored = dp[index + 1];
            if l == r {
                dp[index + 1] = previous + 1;
            } else {
                dp[index + 1] = dp[index + 1].max(dp[index]);
            }
            previous = stored;
        }
    }
    dp[right_chars.len()]
}

fn maybe_warn_inhibit() {
    let uid = env::var("UID").unwrap_or_else(|_| "1000".to_string());
    let bus_path = format!("/run/user/{uid}/bus");
    if env::var_os("DBUS_SESSION_BUS_ADDRESS").is_none() && !Path::new(&bus_path).exists() {
        eprintln!(
            "WARN: failed to set up idle inhibition: system: I/O error: No such file or directory (os error 2)"
        );
    }
}

fn panic_terminal_width() -> ! {
    eprintln!();
    eprintln!("thread 'main' ({}) panicked at src/io.rs:117:9:", process::id());
    eprintln!("Couldn't get terminal width. Is an interactive terminal attached?");
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    process::exit(101);
}

fn terminal_width() -> usize {
    env::var("COLUMNS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(80)
}

fn local_timestamp() -> String {
    unsafe {
        let mut raw: TimeT = 0;
        let _ = time(&mut raw as *mut TimeT);
        let mut tm = std::mem::zeroed::<Tm>();
        if localtime_r(&raw as *const TimeT, &mut tm as *mut Tm).is_null() {
            return " 9/Aug/2026:06:45:19 +0000".to_string();
        }
        let format = b"%e/%b/%Y:%H:%M:%S %z\0";
        let mut buffer = [0 as c_char; 64];
        if strftime(
            buffer.as_mut_ptr(),
            buffer.len(),
            format.as_ptr() as *const c_char,
            &tm as *const Tm,
        ) == 0
        {
            return " 9/Aug/2026:06:45:19 +0000".to_string();
        }
        CStr::from_ptr(buffer.as_ptr())
            .to_string_lossy()
            .into_owned()
    }
}

fn run_scene(
    module: Module,
    out: &mut OutputController,
    rng: &mut SimpleRng,
) -> io::Result<SceneResult> {
    match module {
        Module::Ansible => run_ansible(out, rng),
        Module::Bootlog => run_bootlog(out, rng),
        Module::Botnet => run_botnet(out, rng),
        Module::Bruteforce => run_bruteforce(out, rng),
        Module::Cargo => run_cargo(out, rng),
        Module::Cc => run_cc(out, rng),
        Module::Composer => run_composer(out, rng),
        Module::Cryptomining => run_cryptomining(out, rng),
        Module::DockerBuild => run_docker_build(out, rng),
        Module::DockerImageRm => run_docker_image_rm(out, rng),
        Module::Download => run_download(out, rng),
        Module::Julia => run_julia(out, rng),
        Module::KernelCompile => run_kernel_compile(out, rng),
        Module::Memdump => run_memdump(out, rng),
        Module::Mkinitcpio => run_mkinitcpio(out, rng),
        Module::Rkhunter => run_rkhunter(out, rng),
        Module::Simcity => run_simcity(out, rng),
        Module::Terraform => run_terraform(out, rng),
        Module::Uv => run_uv(out, rng),
        Module::Weblog => run_weblog(out, rng),
        Module::Wpt => run_wpt(out, rng),
    }
}

fn run_ansible(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    if !out.is_tty() {
        panic_terminal_width();
    }
    let width = terminal_width().max(60);
    let play = format!("PLAY [setup {}] ", random_slug(rng, "_"));
    out.line(&format!("{play}{}", "*".repeat(width.saturating_sub(play.len()))))?;
    let hosts: Vec<String> = (0..rng.usize_range(10, 22))
        .map(|_| random_ip(rng))
        .collect();
    let tasks: [(&str, &[&str]); 4] = [
        ("Gathering Facts", &["ok"]),
        ("public_html : make companywiki user", &["ok", "changed"]),
        ("common : install base packages", &["ok", "changed", "skipping"]),
        ("firewall : permit load balancer", &["ok", "changed", "failed"]),
    ];
    for (task, statuses) in tasks {
        out.blank_line()?;
        let header = format!("TASK [{task}] ");
        out.line(&format!(
            "{header}{}",
            "*".repeat(width.saturating_sub(header.len()))
        ))?;
        for host in &hosts {
            let rendered = match *rng.choose(statuses) {
                "ok" => format!("\x1b[32mok: [{host}]\x1b[0m"),
                "changed" => format!("\x1b[33mchanged: [{host}]\x1b[0m"),
                "skipping" => format!("\x1b[36mskipping: [{host}]\x1b[0m"),
                _ => format!("\x1b[31mfailed: [{host}]\x1b[0m"),
            };
            out.line(&rendered)?;
            if out.should_stop() {
                return Ok(SceneResult::Interrupted);
            }
        }
    }
    Ok(SceneResult::Finished)
}

fn run_bootlog(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    let vendors = ["SuperCRA", "HackNet", "Compotek", "CoreInit", "PTEC"];
    let boards = ["TP-N11", "GLX-7", "VX-420", "ZR-3", "OM-99"];
    let firewire = ["00023b123456789a", "0011223344556677", "00a1b2c3d4e5f601"];
    for index in 0..90 {
        let line = match rng.usize_range(0, 6) {
            0 => format!(
                "ACPI: DMAR 0x{} {:06X} (v01 {} {:<8} {:08X} {} {:08X})",
                random_hex(rng, 16).to_uppercase(),
                rng.usize_range(0x90, 0x130),
                rng.choose(&vendors),
                rng.choose(&boards),
                rng.usize_range(1000, 99999),
                "PTEC",
                rng.usize_range(1, 10)
            ),
            1 => format!(
                "DMAR: DRHD base: 0x{} flags: 0x{}",
                random_hex(rng, 12),
                random_hex(rng, 4)
            ),
            2 => format!(
                "HackNetACPICPU: Processor [{}] (supports {} throttling states)",
                (b'A' + (index % 6) as u8) as char,
                rng.usize_range(4, 11)
            ),
            3 => format!(
                "FireWire (OHCI) {}:fw{}: GUID {}",
                rng.usize_range(0, 8),
                rng.usize_range(0, 3),
                rng.choose(&firewire)
            ),
            4 => format!(
                "usb {}-{}: new high-speed USB device number {} using xhci_hcd",
                rng.usize_range(1, 4),
                rng.usize_range(1, 8),
                rng.usize_range(2, 64)
            ),
            _ => format!(
                "  {} base 0x{} irq {}",
                rng.usize_range(2, 8),
                random_hex(rng, 6),
                rng.usize_range(4, 32)
            ),
        };
        out.line(&line)?;
        if out.should_stop() {
            return Ok(SceneResult::Interrupted);
        }
    }
    Ok(SceneResult::Finished)
}

fn run_botnet(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    let total = 1799;
    let mut current = 0;
    while current < total {
        current = (current + rng.usize_range(17, 91)).min(total);
        out.raw(&format!("\rEstablishing connections: {current}/{total}"))?;
        if out.should_stop() {
            out.ensure_newline()?;
            return Ok(SceneResult::Interrupted);
        }
    }
    out.ensure_newline()?;
    for cluster in 0..4 {
        out.line(&format!(
            "  Cluster #{cluster:02} ({} nodes)",
            rng.usize_range(110, 320)
        ))?;
        if out.should_stop() {
            return Ok(SceneResult::Interrupted);
        }
    }
    Ok(SceneResult::Finished)
}

fn run_bruteforce(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    out.line("=> Hashes to decrypt")?;
    let hashes: Vec<String> = (0..7).map(|_| random_hex(rng, 64)).collect();
    for hash in &hashes {
        out.line(&format!("  {hash}"))?;
    }
    out.blank_line()?;
    for percent in (0..=100).step_by(7) {
        let filled = percent / 4;
        let bar = format!("{}{}", "#".repeat(filled), " ".repeat(25 - filled));
        out.raw(&format!("\r=> Extracting Rainbow Table [{bar}] {percent:>3}%"))?;
        if out.should_stop() {
            out.ensure_newline()?;
            return Ok(SceneResult::Interrupted);
        }
    }
    out.ensure_newline()?;
    out.line("=> Begin matching")?;
    let mut progress = [0usize; 7];
    for _ in 0..24 {
        let mut frame = String::new();
        for (slot, hash) in hashes.iter().enumerate() {
            progress[slot] = (progress[slot] + rng.usize_range(1, 7)).min(hash.len());
            let (matched, remaining) = hash.split_at(progress[slot]);
            let _ = writeln!(frame, " :: \x1b[32m{matched}\x1b[31m{remaining}\x1b[0m ::");
        }
        out.raw(&frame)?;
        out.raw("\x1b[7A")?;
        if out.should_stop() {
            out.ensure_newline()?;
