fn run_download(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    if !out.is_tty() {
        panic_terminal_width();
    }
    let filename = random_filename(rng);
    let total_mib = rng.f64_range(8.0, 64.0);
    let mut downloaded = 0.0;
    while downloaded < total_mib {
        downloaded = (downloaded + rng.f64_range(0.6, 3.1)).min(total_mib);
        let percent = ((downloaded / total_mib) * 100.0).round() as u64;
        let filled = ((percent as usize) * 26 / 100).min(26);
        let bar = format!("{}{}", "█".repeat(filled), " ".repeat(26 - filled));
        let rate = rng.f64_range(0.6, 8.5);
        let eta = ((total_mib - downloaded) / rate).ceil().max(0.0) as u64;
        out.raw(&format!(
            "\r{filename:<22} {percent:>3}%[{bar}] {downloaded:>5.1}MiB  {rate:>5.1}MiB/s   eta {eta}s"
        ))?;
        if out.should_stop() {
            out.ensure_newline()?;
            return Ok(SceneResult::Interrupted);
        }
    }
    out.ensure_newline()?;
    Ok(SceneResult::Finished)
}

