fn run_memdump(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    let mut address = rng.u64_range(0x1000_0000_0000_0000, 0xf000_0000_0000_0000) & !0xf;
    for _ in 0..132 {
        let bytes: Vec<u8> = (0..16).map(|_| rng.u8()).collect();
        let left = bytes[..8]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        let right = bytes[8..]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<Vec<_>>()
            .join(" ");
        let ascii: String = bytes
            .iter()
            .map(|byte| {
                if byte.is_ascii_graphic() || *byte == b' ' {
                    char::from(*byte)
                } else {
                    '.'
                }
            })
            .collect();
        out.line(&format!("{address:016x}  {left}  {right}  |{ascii}|"))?;
        address = address.wrapping_add(0x10);
        if out.should_stop() {
            return Ok(SceneResult::Interrupted);
        }
    }
    Ok(SceneResult::Finished)
}

