fn run_wpt(out: &mut OutputController, rng: &mut SimpleRng) -> io::Result<SceneResult> {
    let total = rng.usize_range(11_000, 21_000);
    out.line(&format!("Running {total} tests in web-platform-tests"))?;
    out.raw(&format!("\x1b[A\x1b[K[0/{total}] No tests running."))?;
    let mut running = 0usize;
    for _ in 0..24 {
        running += rng.usize_range(1, 12);
        let mut tests = Vec::new();
        for _ in 0..rng.usize_range(2, 8) {
            tests.push(random_wpt_path(rng));
        }
        out.raw(&format!("\x1b[A\x1b[K[{running}/{total}] {} ", tests.join(" ")))?;
        if rng.chance(0.45) {
            let path = random_wpt_path(rng);
            out.ensure_newline()?;
            out.line(&format!("    ▶ Unexpected subtest result in {path}:"))?;
            out.line(&format!(
                "    │ ERROR [expected PASS] FAIL {} assert_equals: expected {} but got {}",
                random_test_name(rng),
                rng.usize_range(10, 900),
                rng.usize_range(10, 900)
            ))?;
            out.line(&format!("    │   at {}", random_stack_frame(rng)))?;
            out.line(&format!("    └   at {}", random_stack_frame(rng)))?;
        }
        if rng.chance(0.35) {
            let path = random_wpt_path(rng);
            out.ensure_newline()?;
            out.line(&format!("    ▶ Timed out in {path}"))?;
            out.line(&format!(
                "    │ ERROR [expected FAIL] TIMEOUT {} assert_",
                random_test_name(rng)
            ))?;
        }
        if out.should_stop() && running > 20 {
            out.ensure_newline()?;
            return Ok(SceneResult::Interrupted);
        }
    }
    out.ensure_newline()?;
    Ok(SceneResult::Finished)
}

