fn random_title_case(rng: &mut SimpleRng) -> String {
    let word = random_word(rng);
    let mut chars = word.chars();
    let first = chars.next().unwrap_or('A').to_ascii_uppercase();
    format!("{first}{}", chars.as_str())
}

fn random_slug(rng: &mut SimpleRng, separator: &str) -> String {
    format!("{}{}{}", random_word(rng), separator, random_word(rng))
}

fn random_semver(rng: &mut SimpleRng) -> String {
    format!(
        "{}.{}.{}",
        rng.usize_range(0, 3),
        rng.usize_range(0, 40),
        rng.usize_range(0, 40)
    )
}

fn random_symbol(rng: &mut SimpleRng) -> String {
    let pieces = rng.usize_range_inclusive(1, 3);
    let mut parts = Vec::new();
    for _ in 0..pieces {
        parts.push(random_word(rng).to_string());
    }
    parts.join("-")
}

fn random_crate_name(rng: &mut SimpleRng) -> String {
    if rng.chance(0.35) {
        format!("{}-{}", random_word(rng), random_word(rng))
    } else if rng.chance(0.3) {
        format!("{}_{}", random_word(rng), random_word(rng))
    } else {
        random_word(rng).to_string()
    }
}

