fn random_hex(rng: &mut SimpleRng, len: usize) -> String {
    const HEX: &[u8] = b"0123456789abcdef";
    let mut value = String::with_capacity(len);
    for _ in 0..len {
        value.push(HEX[rng.usize_range(0, HEX.len())] as char);
    }
    value
}

