        "drivers/net/wireless/realtek/rtlwifi",
        "fs/nfs",
        "kernel/irq",
        "mm",
        "sound/core",
        "tools/testing/selftests/x86",
    ];
    format!("{}/{}", rng.choose(&roots), random_symbol(rng))
}

fn random_compile_line(rng: &mut SimpleRng) -> String {
    let compilers = ["gcc", "clang"];
    let opts = ["-O0", "-O1", "-O2", "-O3", "-Os"];
    let warnings = [
        "-Wall -Wextra -Wold-style-definition",
        "-Wall -Wno-sign-compare -fgnu89-inline",
        "-Wall -Wno-parentheses -Wundef",
        "-Wall -Wextra -Wundef -Wold-style-definition",
    ];
    let mut includes = Vec::new();
    for _ in 0..rng.usize_range(10, 24) {
        includes.push(format!("-I{}", random_kernel_path(rng)));
    }
    let mut defines = Vec::new();
    for _ in 0..rng.usize_range(2, 7) {
        let define = match rng.usize_range(0, 5) {
            0 => "DEBUG".to_string(),
            1 => "_REENTRANT".to_string(),
            2 => "LIBS_REENTRANT".to_string(),
            3 => format!("MODULE_NAME={}", random_word(rng)),
            _ => format!("NAMESPACE={}", random_word(rng)),
        };
        defines.push(format!("-D{define}"));
    }
    format!(
        "{} -c {} {} {} {} -o {}.o",
        rng.choose(&compilers),
        rng.choose(&opts),
        rng.choose(&warnings),
        includes.join(" "),
        defines.join(" "),
        random_kernel_path(rng)
    )
}

fn random_wpt_path(rng: &mut SimpleRng) -> String {
    let top = [
        "css",
        "html",
        "encoding",
        "WebGL",
        "webaudio",
        "cookies",
        "streams",
        "webrtc",
        "navigation-api",
        "selectors",
        "svg",
        "canvas",
        "loading",
        "dom",
    ];
    format!(
        "/{}/{}/{}/test-{}.html",
        rng.choose(&top),
        random_word(rng),
        random_word(rng),
        rng.usize_range(1, 500)
    )
}

fn random_test_name(rng: &mut SimpleRng) -> String {
    format!("test_{}{}", random_word(rng), rng.usize_range(1, 400))
}

fn random_stack_frame(rng: &mut SimpleRng) -> String {
    if rng.chance(0.35) {
        "<unknown>".to_string()
    } else {
        format!(
            "http://web-platform.test:8000{}:{}:{}",
            random_wpt_path(rng),
            rng.usize_range(1, 160),
            rng.usize_range(1, 99)
        )
    }
}

